namespace App\Application\Catalog\Service;
use App\Application\Catalog\DTO\Request\CreateExamWithNoticeRequestDto;use App\Application\Catalog\DTO\Response\CreateExamWithNoticeResponseDto;use App\Application\Catalog\Mapper\ExamResponseMapper;use App\Application\Catalog\Mapper\SyllabusProcessingJobResponseMapper;use App\Application\Catalog\Mapper\SyllabusResponseMapper;use App\Application\Catalog\Port\SyllabusDocumentStorageInterface;use App\Application\Catalog\Port\TransactionManagerInterface;use App\Domain\Catalog\Entity\Exam;use App\Domain\Catalog\Entity\Syllabus;use App\Domain\Catalog\Entity\SyllabusProcessingJob;use App\Domain\Catalog\Repository\ExamRepositoryInterface;use App\Domain\Catalog\Repository\SyllabusProcessingJobRepositoryInterface;use App\Domain\Catalog\Repository\SyllabusRepositoryInterface;
final class CreateExamWithNoticeService { public function __construct(private readonly ExamRepositoryInterface $exams,private readonly SyllabusRepositoryInterface $syllabi,private readonly SyllabusProcessingJobRepositoryInterface $jobs,private readonly SyllabusDocumentStorageInterface $storage,private readonly ExamResponseMapper $examsMapper,private readonly SyllabusResponseMapper $syllabiMapper,private readonly SyllabusProcessingJobResponseMapper $jobsMapper,private readonly TransactionManagerInterface $transactions) {} public function create(CreateExamWithNoticeRequestDto $input):CreateExamWithNoticeResponseDto { $name=trim($input->name);$organizer=$input->organizer===null?null:trim($input->organizer);$year=$input->year;$max=(int)(new \DateTimeImmutable('now'))->format('Y')+1;if($name===''||mb_strlen($name)>190||($organizer!==null&&($organizer===''||mb_strlen($organizer)>190))||($year!==null&&($year<1900||$year>$max)))throw new \InvalidArgumentException('Dados do concurso invalidos.');if(($input->documentContents===null)!==($input->documentOriginalName===null)||($input->documentContents===null)!==($input->documentMimeType===null))throw new \InvalidArgumentException('Dados do PDF invalidos.');if($input->documentContents!==null&&($input->documentMimeType!=='application/pdf'||!str_starts_with($input->documentContents,'%PDF-')))throw new \InvalidArgumentException('Informe um PDF valido.');return $this->transactions->transactional(function()use($name,$organizer,$year,$input){$exam=new Exam($this->id(),$name,$organizer,$year);$this->exams->save($exam);if($input->documentContents===null)return new CreateExamWithNoticeResponseDto($this->examsMapper->map($exam),null,null);$hash=hash('sha256',$input->documentContents);$path=$this->storage->store($hash,$input->documentOriginalName,$input->documentContents);$syllabus=new Syllabus($this->id(),$exam->id,'Edital principal',$year===null?null:(string)$year.'-01-01',null,$path,$hash,$input->documentOriginalName,$input->documentMimeType,strlen($input->documentContents));$this->syllabi->save($syllabus);$job=new SyllabusProcessingJob($this->id(),$syllabus->id,$hash,'PENDING',0,null,new \DateTimeImmutable('now'));$this->jobs->save($job);return new CreateExamWithNoticeResponseDto($this->examsMapper->map($exam),$this->syllabiMapper->map($syllabus),$this->jobsMapper->map($job));}); } private function id():string{$b=random_bytes(16);$b[6]=chr((ord($b[6])&15)|64);$b[8]=chr((ord($b[8])&63)|128);return vsprintf('%s%s-%s-%s-%s-%s%s%s',str_split(bin2hex($b),4));} }
